function validate([rings]) {
  if (typeof rings !== 'string' || rings.length % 2 !== 0) return 'rings must have an even length.';
  if (rings.length < 2 || rings.length > 200) return 'rings describes 1 to 100 rings.';
  for (let i = 0; i < rings.length; i += 2) {
    if (!'RGB'.includes(rings[i])) return 'Each colour is R, G or B.';
    if (rings[i + 1] < '0' || rings[i + 1] > '9') return 'Each rod is a digit from 0 to 9.';
  }
  return null;
}

