  const colorsOnRod = new Map();
  for (let i = 0; i < rings.length; i += 2) {
    const color = rings[i];
    const rod = rings[i + 1];
    if (!colorsOnRod.has(rod)) {
      colorsOnRod.set(rod, new Set());
    }
    colorsOnRod.get(rod).add(color);
  }

  let count = 0;
  for (const colors of colorsOnRod.values()) {
    if (colors.size === 3) {
      count++;
    }
  }
  return count;
}

