function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 9);
  // Small inputs often use only a few rods so that some rods collect all three colours.
  const rodCount = size === 'large' ? 1 + Math.floor(rand() * 10) : 1 + Math.floor(rand() * 4);
  const offset = Math.floor(rand() * (11 - rodCount));
  let rings = '';
  for (let i = 0; i < n; i++) {
    rings += 'RGB'[Math.floor(rand() * 3)];
    rings += String(offset + Math.floor(rand() * rodCount));
  }
  return [rings];
}
